//! The module graph of the root build.
//!
//! This is the only place where source modules and their imports are wired.
//! Area files create root modules for tests and executables from the import
//! sets declared here; they wire only modules generated by build steps
//! (exported keymaps) and `addOptions` fixture paths. Import names match the
//! `@import("…")` strings in the sources.
const std = @import("std");
const Config = @import("Config.zig");
const Deps = @import("Deps.zig");
const fw_build = @import("../src/firmware/build.zig");
const native = @import("native.zig");
const Module = std.Build.Module;
const Import = Module.Import;
const Modules = @This();

b: *std.Build,
cfg: Config,
core: Core,
/// Everything built on the firmware package; absent under `-Donly`.
host: ?Host,
/// The DVUI graph; present with `-Ddesktop`.
gui: ?Gui,

/// Modules without the firmware package.
pub const Core = struct {
    owned_zon: *Module,
    uf2: *Module,
    jobs: *Module,
    /// `owned-zon` and `firmware-uf2`: the jobs package's own dependencies.
    jobs_deps: []const Import,
    /// `companion-jobs` alone.
    jobs_only: []const Import,
    release_options: *std.Build.Step.Options,
    bootsel_policy: *Module,
    bootsel_tool: []const Import,
    flash_controller: *Module,
    tray_lifecycle: *Module,
    flash_presenter: *Module,
    geometry: *Module,
    zqlite: ?*Module,
    /// `zqlite` alone, for the persistent practice stores.
    zqlite_only: []const Import,
};

/// Modules on top of the firmware package's processor and keycodes.
pub const Host = struct {
    sources: fw_build.Sources,
    zigmkay: *Module,
    keycodes: *Module,
    layout: *Module,
    defaults: *Module,
    /// A separate default keymap inventory as a test root.
    defaults_test: *Module,
    physical: *Module,
    catalog: *Module,
    protocol: *Module,
    profile: *Module,
    project: *Module,
    /// The project's own imports, for a separate test root of `src/project/root.zig`.
    project_deps: []const Import,
    /// Native input layout (`zkeymap`) and its text composition (`input-source`).
    keymap: *Module,
    input_source: *Module,
    desktop_core: *Module,
    catalog_project: *Module,
    importer: *Module,
    /// The importer package's own imports, for its test root with `test-options`.
    importer_deps: []const Import,
    runner_protocol: *Module,
    runner_client: *Module,
    runner_async: *Module,
    session: *Module,
    /// `layout-model` and `device-protocol`: the session package's own imports.
    session_deps: []const Import,
    /// `session_deps` plus the session package as `companion-model`.
    session_test_deps: []const Import,
    live_adapter: *Module,
    native_hid: *Module,
    /// The curated profile's callback source in the firmware package.
    rollercole_source: std.Build.LazyPath,
    /// Callback handler of the all-actions runner fixture.
    runner_callback_fixture: *Module,
    input_tests: InputTests,

    // Import sets of test and executable roots.
    zigmkay_only: []const Import,
    project_only: []const Import,
    label_deps: []const Import,
    text_deps: []const Import,
    flash_runtime_deps: []const Import,
    event_history_deps: []const Import,
    inspector_session_deps: []const Import,
    live_keyboard_deps: []const Import,
    desktop_integration_deps: []const Import,
    catalog_view_deps: []const Import,
    onboarding_deps: []const Import,
    flash_session_deps: []const Import,
    flash_fixture_deps: []const Import,
    bundle_check_deps: []const Import,
    catalog_export_deps: []const Import,
    processor_contract_deps: []const Import,
    keymap_project: []const Import,
    runner_test_deps: []const Import,
    manifest_fixture_deps: []const Import,
    import_fixture_deps: []const Import,
    native_hid_only: []const Import,
};

/// Test roots of the input package, all on the host target.
pub const InputTests = struct {
    /// `src/input/root.zig` without a native bridge.
    portable: *Module,
    /// `src/input/native_tests.zig` against the US layout fixture.
    us_fixture: *Module,
    /// `src/input/native_tests.zig` against the OS layout (`test-native` only).
    native: *Module,
    /// `src/input/hid_to_platform.test.zig`.
    hid_tables: *Module,
    smoke_deps: []const Import,
};

/// DVUI user-interface modules.
pub const Gui = struct {
    dvui: *Module,
    backend: *Module,
    fonts: *Module,
    ui: *Module,
    events: *Module,
    placement: *Module,
    folder_dialog: *Module,
    tray: *Module,
    native_tray: *Module,
    flash_ui: *Module,
    icons: *Module,
    svg2tvg: *Module,
    physical_ui: *Module,
    practice_ui: *Module,
    editor_frame_ui: *Module,
    native_draft_input: *Module,
    icon_resources: *Module,
    onboarding_ui: *Module,
    companion_window: *Module,
    audit_options: *std.Build.Step.Options,

    vector_test_deps: []const Import,
    application_icons: *Module,
    icon_files: std.Build.LazyPath,
    key_renderer_deps: []const Import,
    dependency_smoke_deps: []const Import,
    physical_smoke_deps: []const Import,
    editor_frame_test_deps: []const Import,
    app_deps: []const Import,
    usb_acceptance_deps: []const Import,
};

pub fn init(b: *std.Build, cfg: Config, deps: Deps) Modules {
    const core = initCore(b, cfg, deps);
    const host = if (deps.firmware) |firmware| initHost(b, cfg, core, firmware) else null;
    const gui = if (host) |h| if (deps.dvui) |dvui| initGui(b, cfg, deps, core, h, dvui) else null else null;
    return .{ .b = b, .cfg = cfg, .core = core, .host = host, .gui = gui };
}

/// A root module for a test or executable at `path` with the given imports.
pub fn root(m: Modules, path: []const u8, imports: []const Import) *Module {
    return m.b.createModule(.{
        .root_source_file = m.b.path(path),
        .target = m.cfg.target,
        .optimize = m.cfg.optimize,
        .imports = imports,
    });
}

fn initCore(b: *std.Build, cfg: Config, deps: Deps) Core {
    const owned_zon = b.createModule(.{ .root_source_file = b.path("src/project/owned_zon.zig") });
    const uf2 = b.createModule(.{ .root_source_file = b.path("src/artifact/uf2.zig") });
    const jobs_deps = dupe(b, &.{ .{ .name = "owned-zon", .module = owned_zon }, .{ .name = "firmware-uf2", .module = uf2 } });
    const jobs = b.createModule(.{ .root_source_file = b.path("src/jobs/root.zig"), .imports = jobs_deps });
    const jobs_only = dupe(b, &.{.{ .name = "companion-jobs", .module = jobs }});
    const release_options = b.addOptions();
    release_options.addOption([]const u8, "application_version", @import("../build.zig.zon").version);
    const appimage_pins = @import("../packaging/appimage-pins.zon");
    inline for (@typeInfo(@TypeOf(appimage_pins)).@"struct".field_names) |field|
        release_options.addOption([]const u8, field, @field(appimage_pins, field));
    const bootsel_policy = b.createModule(.{ .root_source_file = b.path("src/jobs/bootsel_transfer.zig"), .imports = dupe(b, &.{.{ .name = "firmware-uf2", .module = uf2 }}) });
    const bootsel_native = b.createModule(.{ .root_source_file = b.path("src/jobs/bootsel_windows.zig"), .imports = dupe(b, &.{.{ .name = "bootsel-policy", .module = bootsel_policy }}) });
    const flash_controller = b.createModule(.{ .root_source_file = b.path("src/desktop/flash_controller.zig"), .imports = jobs_only });
    return .{
        .owned_zon = owned_zon,
        .uf2 = uf2,
        .jobs = jobs,
        .jobs_deps = jobs_deps,
        .jobs_only = jobs_only,
        .release_options = release_options,
        .bootsel_policy = bootsel_policy,
        .bootsel_tool = dupe(b, &.{ .{ .name = "bootsel-policy", .module = bootsel_policy }, .{ .name = "bootsel-native", .module = bootsel_native } }),
        .flash_controller = flash_controller,
        .tray_lifecycle = b.createModule(.{ .root_source_file = b.path("src/desktop/tray_lifecycle.zig"), .target = cfg.target, .optimize = cfg.optimize }),
        .flash_presenter = b.createModule(.{ .root_source_file = b.path("src/desktop/flash_presenter.zig"), .target = cfg.target, .optimize = cfg.optimize, .imports = dupe(b, &.{.{ .name = "flash-controller", .module = flash_controller }}) }),
        .geometry = b.createModule(.{ .root_source_file = b.path("src/desktop/geometry.zig") }),
        .zqlite = deps.zqlite,
        .zqlite_only = if (deps.zqlite) |zqlite| dupe(b, &.{.{ .name = "zqlite", .module = zqlite }}) else &.{},
    };
}

fn initHost(b: *std.Build, cfg: Config, core: Core, firmware: *std.Build.Dependency) Host {
    const t = cfg.target;
    const o = cfg.optimize;
    const sources: fw_build.Sources = .{
        .keyboards = firmware.path("keyboards"),
        .processor = firmware.path("zigmkay/src/root.zig"),
        .keycodes = firmware.path("zkeycodes/root.zig"),
    };
    const zigmkay = firmware.module("zigmkay");
    const zigmkay_only = dupe(b, &.{.{ .name = "zigmkay", .module = zigmkay }});
    const keycodes = b.createModule(.{ .root_source_file = sources.keycodes, .imports = zigmkay_only });
    const layout = b.createModule(.{ .root_source_file = b.path("src/layout/root.zig"), .imports = zigmkay_only });
    const physical = b.createModule(.{ .root_source_file = b.path("src/catalog/lk7_physical_layout.zig"), .imports = dupe(b, &.{.{ .name = "layout-model", .module = layout }}) });
    const defaults = fw_build.defaultKeymaps(b, sources, zigmkay, keycodes);
    const catalog = b.createModule(.{ .root_source_file = b.path("src/catalog/root.zig"), .target = t, .optimize = o, .imports = dupe(b, &.{
        .{ .name = "firmware-defaults", .module = defaults },
        .{ .name = "layout-model", .module = layout },
        .{ .name = "lk7-physical", .module = physical },
    }) });
    for (fw_build.boards.entries, 0..) |board, index|
        catalog.addAnonymousImport(b.fmt("default-source-{d}", .{index}), .{ .root_source_file = firmware.path(b.fmt("keyboards/{s}", .{board.default_keymap})) });
    catalog.addAnonymousImport("janbeelte-shared-source", .{ .root_source_file = firmware.path("keyboards/my_keyboards/janbeelte/keymap_shared.zig") });
    const protocol = b.createModule(.{ .root_source_file = b.path("src/firmware/protocol.zig"), .imports = zigmkay_only });
    const keymap = inputKeymap(b, b.path("src/input/root.zig"), keycodes, t, .native);
    const input_source = b.createModule(.{ .root_source_file = b.path("src/input/input_source.zig"), .target = t, .imports = dupe(b, &.{.{ .name = "zkeymap", .module = keymap }}) });
    const profile = b.createModule(.{ .root_source_file = b.path("src/firmware/curated_profile.zig"), .imports = dupe(b, &.{.{ .name = "firmware-defaults", .module = defaults }}) });
    const project_deps = dupe(b, &.{
        .{ .name = "layout-model", .module = layout },
        .{ .name = "device-protocol", .module = protocol },
        .{ .name = "rollercole-profile", .module = profile },
        .{ .name = "lk7-physical", .module = physical },
        .{ .name = "owned-zon", .module = core.owned_zon },
    });
    const project = b.createModule(.{ .root_source_file = b.path("src/project/root.zig"), .imports = project_deps });
    project.addAnonymousImport("rollercole-source", .{ .root_source_file = rollercoleSource(firmware) });
    const project_only = dupe(b, &.{.{ .name = "project", .module = project }});
    const runner_protocol = b.createModule(.{ .root_source_file = b.path("src/runner/protocol.zig"), .imports = dupe(b, &.{
        .{ .name = "zigmkay", .module = zigmkay },
        .{ .name = "owned-zon", .module = core.owned_zon },
    }) });
    const runner_client = b.createModule(.{ .root_source_file = b.path("src/runner/client.zig"), .imports = dupe(b, &.{
        .{ .name = "runner-protocol", .module = runner_protocol },
        .{ .name = "companion-jobs", .module = core.jobs },
        .{ .name = "owned-zon", .module = core.owned_zon },
    }) });
    const runner_async = b.createModule(.{ .root_source_file = b.path("src/runner/async_client.zig"), .imports = dupe(b, &.{
        .{ .name = "runner-client", .module = runner_client },
        .{ .name = "runner-protocol", .module = runner_protocol },
        .{ .name = "companion-jobs", .module = core.jobs },
    }) });
    const session_deps = dupe(b, &.{ .{ .name = "layout-model", .module = layout }, .{ .name = "device-protocol", .module = protocol } });
    const session = b.createModule(.{ .root_source_file = b.path("src/session/root.zig"), .imports = session_deps });
    const live_adapter = b.createModule(.{ .root_source_file = b.path("src/session/live_adapter.zig"), .imports = dupe(b, &.{
        .{ .name = "device-protocol", .module = protocol },
        .{ .name = "companion-model", .module = session },
    }) });
    const native_hid = b.createModule(.{ .root_source_file = b.path("src/platform/native_hid.zig"), .imports = dupe(b, &.{.{ .name = "live-adapter", .module = live_adapter }}) });
    const catalog_project = b.createModule(.{ .root_source_file = b.path("src/firmware/catalog_project.zig"), .target = t, .optimize = o, .imports = dupe(b, &.{
        .{ .name = "catalog", .module = catalog },
        .{ .name = "project", .module = project },
        .{ .name = "layout-model", .module = layout },
    }) });
    const importer_deps = dupe(b, &.{
        .{ .name = "project", .module = project },
        .{ .name = "catalog-project", .module = catalog_project },
        .{ .name = "catalog", .module = catalog },
        .{ .name = "layout-model", .module = layout },
        .{ .name = "companion-jobs", .module = core.jobs },
    });
    const importer = b.createModule(.{ .root_source_file = b.path("src/importer/root.zig"), .target = t, .optimize = o, .imports = importer_deps });
    const desktop_core = b.createModule(.{ .root_source_file = b.path("src/desktop/root.zig"), .target = t, .optimize = o, .imports = dupe(b, &.{
        .{ .name = "project", .module = project },
        .{ .name = "layout-model", .module = layout },
        .{ .name = "zkeymap", .module = keymap },
        .{ .name = "zkeycodes", .module = keycodes },
        .{ .name = "input-source", .module = input_source },
        .{ .name = "companion-jobs", .module = core.jobs },
        .{ .name = "zqlite", .module = core.zqlite.? },
        .{ .name = "flash-controller", .module = core.flash_controller },
        .{ .name = "desktop-geometry", .module = core.geometry },
        .{ .name = "flash-presenter", .module = core.flash_presenter },
        .{ .name = "tray-lifecycle", .module = core.tray_lifecycle },
        .{ .name = "device-protocol", .module = protocol },
        .{ .name = "keymap-importer", .module = importer },
        .{ .name = "runner-async", .module = runner_async },
        .{ .name = "session", .module = session },
    }) });
    const label_deps = dupe(b, &.{
        .{ .name = "project", .module = project },
        .{ .name = "layout-model", .module = layout },
        .{ .name = "zkeymap", .module = keymap },
        .{ .name = "zkeycodes", .module = keycodes },
    });
    return .{
        .sources = sources,
        .zigmkay = zigmkay,
        .keycodes = keycodes,
        .layout = layout,
        .defaults = defaults,
        .defaults_test = defaults_test: {
            const module = fw_build.defaultKeymaps(b, sources, zigmkay, keycodes);
            module.resolved_target = t;
            module.optimize = o;
            break :defaults_test module;
        },
        .physical = physical,
        .catalog = catalog,
        .protocol = protocol,
        .profile = profile,
        .project = project,
        .project_deps = project_deps,
        .keymap = keymap,
        .input_source = input_source,
        .desktop_core = desktop_core,
        .catalog_project = catalog_project,
        .importer = importer,
        .importer_deps = importer_deps,
        .runner_protocol = runner_protocol,
        .runner_client = runner_client,
        .runner_async = runner_async,
        .session = session,
        .session_deps = session_deps,
        .session_test_deps = dupe(b, &.{
            .{ .name = "layout-model", .module = layout },
            .{ .name = "device-protocol", .module = protocol },
            .{ .name = "companion-model", .module = session },
        }),
        .live_adapter = live_adapter,
        .native_hid = native_hid,
        .rollercole_source = rollercoleSource(firmware),
        .runner_callback_fixture = b.createModule(.{ .root_source_file = b.path("src/runner/callback_fixture.zig"), .imports = zigmkay_only }),
        .input_tests = initInputTests(b, keycodes, keymap, input_source),
        .zigmkay_only = zigmkay_only,
        .project_only = project_only,
        .label_deps = label_deps,
        .text_deps = dupe(b, &.{ .{ .name = "layout-model", .module = layout }, .{ .name = "input-source", .module = input_source } }),
        .flash_runtime_deps = dupe(b, &.{ .{ .name = "companion-jobs", .module = core.jobs }, .{ .name = "flash-controller", .module = core.flash_controller } }),
        .event_history_deps = dupe(b, &.{.{ .name = "device-protocol", .module = protocol }}),
        .inspector_session_deps = dupe(b, &.{ .{ .name = "project", .module = project }, .{ .name = "layout-model", .module = layout } }),
        .live_keyboard_deps = dupe(b, &.{
            .{ .name = "session", .module = session },
            .{ .name = "device-protocol", .module = protocol },
            .{ .name = "layout-model", .module = layout },
            .{ .name = "project", .module = project },
            .{ .name = "zkeymap", .module = keymap },
            .{ .name = "zkeycodes", .module = keycodes },
        }),
        .desktop_integration_deps = dupe(b, &.{
            .{ .name = "desktop-core", .module = desktop_core },
            .{ .name = "project", .module = project },
            .{ .name = "companion-jobs", .module = core.jobs },
        }),
        .catalog_view_deps = dupe(b, &.{ .{ .name = "desktop-core", .module = desktop_core }, .{ .name = "catalog", .module = catalog } }),
        .onboarding_deps = dupe(b, &.{ .{ .name = "desktop-core", .module = desktop_core }, .{ .name = "project", .module = project } }),
        .flash_session_deps = dupe(b, &.{
            .{ .name = "desktop-core", .module = desktop_core },
            .{ .name = "companion-jobs", .module = core.jobs },
            .{ .name = "project", .module = project },
        }),
        .flash_fixture_deps = dupe(b, &.{ .{ .name = "desktop-core", .module = desktop_core }, .{ .name = "project", .module = project } }),
        .bundle_check_deps = dupe(b, &.{
            .{ .name = "desktop-core", .module = desktop_core },
            .{ .name = "project", .module = project },
            .{ .name = "catalog-project", .module = catalog_project },
            .{ .name = "companion-jobs", .module = core.jobs },
            .{ .name = "catalog-inventory", .module = catalog },
        }),
        .catalog_export_deps = dupe(b, &.{ .{ .name = "catalog-project", .module = catalog_project }, .{ .name = "project", .module = project } }),
        .processor_contract_deps = dupe(b, &.{ .{ .name = "zigmkay", .module = zigmkay }, .{ .name = "layout-model", .module = layout } }),
        .keymap_project = dupe(b, &.{.{ .name = "keymap-project", .module = project }}),
        .runner_test_deps = dupe(b, &.{
            .{ .name = "runner-protocol", .module = runner_protocol },
            .{ .name = "zigmkay", .module = zigmkay },
            .{ .name = "companion-jobs", .module = core.jobs },
            .{ .name = "owned-zon", .module = core.owned_zon },
            .{ .name = "runner-client", .module = runner_client },
            .{ .name = "project", .module = project },
            .{ .name = "runner-async", .module = runner_async },
            .{ .name = "desktop-core", .module = desktop_core },
        }),
        .manifest_fixture_deps = dupe(b, &.{ .{ .name = "project", .module = project }, .{ .name = "companion-jobs", .module = core.jobs } }),
        .import_fixture_deps = dupe(b, &.{ .{ .name = "keymap-importer", .module = importer }, .{ .name = "project", .module = project } }),
        .native_hid_only = dupe(b, &.{.{ .name = "native-hid", .module = native_hid }}),
    };
}

fn initGui(b: *std.Build, cfg: Config, deps: Deps, core: Core, host: Host, dvui_dep: *std.Build.Dependency) Gui {
    const t = cfg.target;
    const o = cfg.optimize;
    const dvui = dvui_dep.module("dvui_sdl3");
    const backend = dvui_dep.module("sdl3");
    const sdl = backend.import_table.get("sdl3-c").?;
    const icons = deps.icons.?.module("icons");
    const svg2tvg = deps.svg2tvg.?.module("svg2tvg");
    const icon_generator = b.addExecutable(.{
        .name = "generate-application-icons",
        .root_module = b.createModule(.{
            .root_source_file = b.path("tools/generate_application_icons.zig"),
            .target = b.graph.host,
            .optimize = .ReleaseSafe,
            .imports = &.{.{ .name = "svg2tvg", .module = svg2tvg }},
        }),
    });
    const generate_icons = b.addRunArtifact(icon_generator);
    generate_icons.addFileArg(b.path("packaging/icons/zigmkay.svg"));
    const icon_files = generate_icons.addOutputDirectoryArg("icons");
    const dvui_only = dupe(b, &.{.{ .name = "dvui", .module = dvui }});
    const application_icons = b.createModule(.{
        .root_source_file = b.path("src/desktop/application_icons.zig"),
        .target = t,
        .optimize = o,
        .imports = dvui_only,
    });
    for ([_][]const u8{ "tray.png", "tray-template.png", "tray.ico", "window.png", "window@2x.png" }) |name|
        application_icons.addAnonymousImport(name, .{ .root_source_file = icon_files.path(b, name) });
    const sdl_only = dupe(b, &.{.{ .name = "sdl3-c", .module = sdl }});
    const placement = b.createModule(.{ .root_source_file = b.path("src/platform/window_placement.zig"), .target = t, .imports = sdl_only });
    const folder_dialog = b.createModule(.{ .root_source_file = b.path("src/platform/folder_dialog.zig"), .target = t, .imports = sdl_only });
    const fonts = b.createModule(.{ .root_source_file = b.path("src/desktop/fonts.zig"), .target = t, .imports = dvui_only });
    const inter = deps.inter.?;
    fonts.addAnonymousImport("inter-regular", .{ .root_source_file = inter.path("extras/ttf/Inter-Regular.ttf") });
    fonts.addAnonymousImport("inter-semibold", .{ .root_source_file = inter.path("extras/ttf/Inter-SemiBold.ttf") });
    const icon_resources = desktopModule(b, cfg, "icon_resources.zig", &.{
        .{ .name = "desktop-core", .module = host.desktop_core },
        .{ .name = "icons", .module = icons },
        .{ .name = "svg2tvg", .module = svg2tvg },
    });
    const ui = b.createModule(.{ .root_source_file = b.path("src/desktop/ui.zig"), .target = t, .imports = dupe(b, &.{
        .{ .name = "dvui", .module = dvui },
        .{ .name = "editor-fonts", .module = fonts },
        .{ .name = "desktop-geometry", .module = core.geometry },
        .{ .name = "desktop-core", .module = host.desktop_core },
        .{ .name = "icon-resources", .module = icon_resources },
    }) });
