fn initInputTests(b: *std.Build, keycodes: *Module, keymap: *Module, input_source: *Module) InputTests {
    const host = b.graph.host;
    const hid = b.createModule(.{ .root_source_file = b.path("src/input/hid_to_platform.zig"), .imports = dupe(b, &.{.{ .name = "zkeycodes", .module = keycodes }}) });
    const hid_deps = dupe(b, &.{ .{ .name = "zkeycodes", .module = keycodes }, .{ .name = "hid_to_platform", .module = hid } });
    return .{
        .portable = inputKeymap(b, b.path("src/input/root.zig"), keycodes, host, .portable),
        .us_fixture = inputKeymap(b, b.path("src/input/native_tests.zig"), keycodes, host, .us_fixture),
        .native = inputKeymap(b, b.path("src/input/native_tests.zig"), keycodes, host, .native),
        .hid_tables = b.createModule(.{ .root_source_file = b.path("src/input/hid_to_platform.test.zig"), .target = host, .imports = hid_deps }),
        .smoke_deps = dupe(b, &.{ .{ .name = "zkeymap", .module = keymap }, .{ .name = "input-source", .module = input_source } }),
    };
}

/// How an input keymap resolves the OS keyboard layout.
pub const InputBackend = enum {
    /// The target's native bridge where one exists.
    native,
    /// No native bridge: fixed labels only.
    portable,
    /// The deterministic US layout fixture.
    us_fixture,
};

/// The input keymap package rooted at `root_file`, with its options and,
/// for `.native`, the existing platform C bridge.
pub fn inputKeymap(b: *std.Build, root_file: std.Build.LazyPath, keycodes: *Module, target: std.Build.ResolvedTarget, backend: InputBackend) *Module {
    const available = backend == .native and switch (target.result.os.tag) {
        .macos, .windows => true,
        .linux => b.graph.host.result.os.tag == .linux,
        else => false,
    };
    const options = b.addOptions();
    options.addOption(bool, "native_available", available);
    options.addOption(bool, "us_fixture", backend == .us_fixture);
    const module = b.createModule(.{ .root_source_file = root_file, .target = target, .imports = dupe(b, &.{.{ .name = "zkeycodes", .module = keycodes }}) });
    module.addOptions("options", options);
    if (!available) return module;
    module.link_libc = true;
    switch (target.result.os.tag) {
        .macos => {
            module.addCSourceFile(.{ .file = b.path("src/input/platform/macos.c"), .flags = &.{"-std=c11"} });
            module.linkFramework("Carbon", .{});
        },
        .windows => {
            module.addCSourceFile(.{ .file = b.path("src/input/platform/windows.c"), .flags = &.{"-std=c11"} });
            module.linkSystemLibrary("user32", .{});
        },
        .linux => {
            module.addCSourceFile(.{ .file = b.path("src/input/platform/linux.c"), .flags = &.{"-std=c11"} });
            module.linkSystemLibrary("xkbcommon", .{});
            native.linuxPaths(b, module, target);
        },
        else => unreachable,
    }
    return module;
}

/// The historical callback source of the curated profile.
pub fn rollercoleSource(firmware: *std.Build.Dependency) std.Build.LazyPath {
    return firmware.path("keyboards/my_keyboards/rollercole/shared_keymap_3x5_2.zig");
}

fn desktopModule(b: *std.Build, cfg: Config, name: []const u8, imports: []const Import) *Module {
    return b.createModule(.{
        .root_source_file = b.path(b.fmt("src/desktop/{s}", .{name})),
        .target = cfg.target,
        .optimize = cfg.optimize,
        .imports = dupe(b, imports),
    });
}

fn dupe(b: *std.Build, imports: []const Import) []const Import {
    return b.allocator.dupe(Import, imports) catch @panic("OOM");
}
